   const c=p.chains[this.selection];if(c){const b=base+'.chains.'+this.selection;props.innerHTML+='<h3>'+esc(c.name)+'</h3>'+this.field('이름',b+'.name',c.name)+this.field('원본 체인',b+'.source',c.source,'text',[['','없음'],...(this.sourceRig?.chains||[]).map(c=>[c.name,c.name])])+this.field('대상 체인',b+'.target',c.target,'text',[['','없음'],...(this.targetRig?.chains||[]).map(c=>[c.name,c.name])])+this.field('회전',b+'.rotation',c.rotation,'text',retargetRotationModes.map(v=>[v,{interpolated:'체인 길이 보간',oneToOne:'루트부터 1:1',reversed:'끝부터 1:1',none:'입력 유지'}[v]]))+this.field('회전 Alpha',b+'.rotationAlpha',c.rotationAlpha,'number')+this.field('위치',b+'.translation',c.translation,'text',retargetTranslationModes.map(v=>[v,{none:'입력 유지',scaled:'기준 차이 · 배율',absolute:'원본 절대 위치'}[v]]))+this.field('위치 Alpha',b+'.translationAlpha',c.translationAlpha,'number')+'<details><summary>IK 목표 보정</summary>'+this.field('IK',''+b+'.ik',c.ik,'checkbox')+this.field('목표 위치 Alpha',b+'.ikPosition',c.ikPosition,'number')+this.field('목표 회전 Alpha',b+'.ikRotation',c.ikRotation,'number')+this.vector('목표 위치 보정',b+'.offset',c.offset)+this.field('허용 오차',b+'.precision',c.precision,'number')+this.field('최대 반복',b+'.iterations',c.iterations,'number')+'</details><button data-rt-act="remove-map">매핑 삭제</button>';}
   main.innerHTML='<div class="gameplay-toolbar"><button data-rt-act="map-exact">정확히 매핑</button><button data-rt-act="map-empty">빈 체인 매핑</button><button data-rt-act="map-fuzzy">이름으로 매핑</button><button data-rt-act="clear-map">매핑 지우기</button></div><div class="retarget-preview-options"><label>원본 <select data-rt-source>'+this.actorChoices().map(([v,l])=>'<option value="'+esc(v)+'" '+(v===this.source?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select></label><label>대상 <select data-rt-target>'+this.actorChoices().map(([v,l])=>'<option value="'+esc(v)+'" '+(v===this.target?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select></label><label>원본 클립 <select data-rt-clip><option value="">현재 포즈</option>'+(this.hooks.world().groups.get(this.source)?.userData.animations||[]).map(c=>'<option '+(c.name===this.sourceClip?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><button data-rt-act="preview">'+icon('play')+' 미리보기</button></div><div data-rt-preview></div><div class="retarget-playback"><button data-rt-act="play" aria-label="미리보기 재생 / 일시정지">'+icon(this.playing?'pause':'play')+'</button><button data-rt-act="rewind" aria-label="처음으로">'+icon('skip')+'</button><input data-rt-time type="number" min="0" step=".05" value="'+this.time+'" aria-label="미리보기 시간"><output data-rt-status role="status"></output></div>';
